-- Recovered verbatim from the production Supabase migration ledger for L0 replay parity.
create table if not exists public.hq_workforce_handoffs(id uuid primary key default gen_random_uuid(),handoff_key text not null unique,work_item_id uuid,from_lane_key text not null,to_lane_key text not null,from_worker_id uuid references public.hq_workforce_workers(id),to_worker_id uuid references public.hq_workforce_workers(id),reason text not null,payload jsonb not null default '{}'::jsonb,requested_fact_keys text[] not null default '{}'::text[],materialized_context jsonb not null default '[]'::jsonb,status text not null check(status in ('requested','accepted','denied','completed')),violation_code text,created_at timestamptz not null default now(),accepted_at timestamptz,completed_at timestamptz); alter table public.hq_workforce_handoffs enable row level security;
create or replace function public.hq_workforce_prepare_handoff(p_handoff_key text,p_work_item_id uuid,p_from_lane text,p_to_lane text,p_reason text,p_requested_fact_keys text[]) returns uuid language plpgsql security invoker set search_path=public as $$ declare fw uuid; tw uuid; twk text; sid uuid; ctx jsonb; hid uuid; bad int; expected int:=cardinality(coalesce(p_requested_fact_keys,'{}')); actual int; begin select owner_worker_id into fw from public.hq_workforce_lanes where lane_key=p_from_lane and active; select l.owner_worker_id,w.worker_key into tw,twk from public.hq_workforce_lanes l join public.hq_workforce_workers w on w.id=l.owner_worker_id where l.lane_key=p_to_lane and l.active and w.status='active'; if fw is null or tw is null then raise exception 'Active lane ownership required'; end if; select id into sid from public.hq_context_scopes where scope_type='worker' and scope_owner_key=twk; if sid is null then insert into public.hq_workforce_handoffs(handoff_key,work_item_id,from_lane_key,to_lane_key,from_worker_id,to_worker_id,reason,requested_fact_keys,status,violation_code) values(p_handoff_key,p_work_item_id,p_from_lane,p_to_lane,fw,tw,p_reason,coalesce(p_requested_fact_keys,'{}'),'denied','RECEIVER_SCOPE_MISSING') returning id into hid; return hid; end if; select count(*) into bad from unnest(coalesce(p_requested_fact_keys,'{}')) k where not public.hq_context_scope_allows(sid,k); if bad>0 then insert into public.hq_workforce_handoffs(handoff_key,work_item_id,from_lane_key,to_lane_key,from_worker_id,to_worker_id,reason,requested_fact_keys,status,violation_code) values(p_handoff_key,p_work_item_id,p_from_lane,p_to_lane,fw,tw,p_reason,p_requested_fact_keys,'denied','HANDOFF_SCOPE_VIOLATION') returning id into hid; return hid; end if; select coalesce(jsonb_agg(jsonb_build_object('fact_key',c.fact_key,'value',c.value,'confidence',c.confidence,'computed_at',c.computed_at,'freshness_expires_at',c.freshness_expires_at,'fact_definition_id',c.fact_definition_id)),'[]'::jsonb),count(*) into ctx,actual from public.hq_context_facts_cache c join public.hq_context_fact_definitions d on d.id=c.fact_definition_id where c.scope_id=sid and c.fact_key=any(coalesce(p_requested_fact_keys,'{}')) and d.retired_at is null and c.freshness_expires_at>now(); if actual<expected then insert into public.hq_workforce_handoffs(handoff_key,work_item_id,from_lane_key,to_lane_key,from_worker_id,to_worker_id,reason,requested_fact_keys,materialized_context,status,violation_code) values(p_handoff_key,p_work_item_id,p_from_lane,p_to_lane,fw,tw,p_reason,p_requested_fact_keys,ctx,'denied','HANDOFF_CONTEXT_UNAVAILABLE_OR_STALE') returning id into hid; return hid; end if; insert into public.hq_workforce_handoffs(handoff_key,work_item_id,from_lane_key,to_lane_key,from_worker_id,to_worker_id,reason,requested_fact_keys,materialized_context,status,accepted_at) values(p_handoff_key,p_work_item_id,p_from_lane,p_to_lane,fw,tw,p_reason,p_requested_fact_keys,ctx,'accepted',now()) returning id into hid; return hid; end $$;
revoke all on table public.hq_workforce_handoffs from anon,authenticated; revoke all on function public.hq_workforce_prepare_handoff(text,uuid,text,text,text,text[]) from public,anon,authenticated;
